---@alias gcp.contactcenterinsights_v1.GoogleCloudContactcenterinsightsV1ConversationCorrelationInfoCorrelationTypesItemEnumList (gcp.contactcenterinsights_v1.GoogleCloudContactcenterinsightsV1ConversationCorrelationInfoCorrelationTypesItemEnum|string)[]

