---@field alternateIds? gcp.contactcenterinsights_v1.StringList Output only. Alternative IDs for this revision of the scorecard, e.g., `latest`.
---@field createTime? string Output only. The timestamp that the revision was created.
---@field state? gcp.contactcenterinsights_v1.GoogleCloudContactcenterinsightsV1QaScorecardRevisionStateEnum Output only. State of the scorecard revision, indicating whether it's ready to be used in analysis.
---@field satisfiesPzi? boolean Output only. Whether this resource is zone isolated.

---@alias gcp.contactcenterinsights_v1.GoogleCloudContactcenterinsightsV1QaScorecardRevisionList gcp.contactcenterinsights_v1.GoogleCloudContactcenterinsightsV1QaScorecardRevision[]

---@alias gcp.contactcenterinsights_v1.GoogleCloudContactcenterinsightsV1QaScorecardRevisionStateEnum "STATE_UNSPECIFIED"|"EDITABLE"|"TRAINING"|"TRAINING_FAILED"|"READY"|"DELETING"|"TRAINING_CANCELLED"

---@alias gcp.contactcenterinsights_v1.GoogleCloudContactcenterinsightsV1QaScorecardSourceEnum "QA_SCORECARD_SOURCE_UNSPECIFIED"|"QA_SCORECARD_SOURCE_CUSTOMER_DEFINED"|"QA_SCORECARD_SOURCE_DISCOVERY_ENGINE"|"QA_SCORECARD_SOURCE_INTENT_TAXONOMY"

